import { Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;

  const nodeGroup = new Group();

  // --- Textured Plane ---
  const texMaterial = new MeshBasicNodeMaterial();
  const aspect = 320 / 512; // height / width from atlas source rect
  const plane = new Mesh(new PlaneGeometry(7, 7 * aspect), texMaterial);
  // Ensure plane faces camera (default is XY plane facing +Z)
  plane.position.set(0, 0, 0);
  nodeGroup.add(plane);

  // Load texture asynchronously; material will update when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texMaterial.map = tex;
      texMaterial.needsUpdate = true;
    });
  }

  // --- Text Content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  items.forEach((item) => {
    const txtOpts = {
      fontSize: item.typography?.fontSize ?? 96,
      color: item.role === 'headline' ? config.visual?.colors?.paper ?? '#e8ecf2' : '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, txtOpts);
    // Position text slightly in front of plane to avoid Z‑fighting
    txtObj.position.set(0, 0, 0.01);
    nodeGroup.add(txtObj);
  });

  // --- Cinematic Primitives (if any) ---
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const result = fn(nodeGroup, prim.params);
        if (result && typeof result.cleanup === 'function') {
          primitiveCleanups.push(result.cleanup);
        }
        // Store timeline for later disposal if present
        if (result && result.timeline) {
          primitiveCleanups.push(() => result.timeline.kill());
        }
      }
    });
  }

  // --- User Data Handlers Placeholder ---
  nodeGroup.userData.handlers = {};

  // --- Cleanup ---
  nodeGroup.userData.cleanup = () => {
    // Dispose material and texture
    if (texMaterial.map) {
      texMaterial.map.dispose();
    }
    texMaterial.dispose();

    // Kill any GSAP timelines (none in this node but safe guard)
    if (typeof gsap !== 'undefined' && gsap.globalTimeline) {
      gsap.globalTimeline.clear();
    }

    // Run primitive cleanups
    primitiveCleanups.forEach((fn) => {
      try {
        fn();
      } catch (_) {}
    });
  };

  return nodeGroup;
}
